solution.solution.cpp:
bool isPowerOfTwo(unsigned int n)
{
    return n != 0 && (n & (n - 1)) == 0;
}

unitTests:
TEST("powers of two") { CHECK(isPowerOfTwo(1)); CHECK(isPowerOfTwo(2)); CHECK(isPowerOfTwo(64)); CHECK(isPowerOfTwo(1024)); }
TEST("other numbers") { CHECK(!isPowerOfTwo(3)); CHECK(!isPowerOfTwo(6)); CHECK(!isPowerOfTwo(100)); }
TEST("zero is not a power of two") { CHECK(!isPowerOfTwo(0)); }

